			text = [=[El mekigeniero Sicco Thermaplugg fue en otro tiempo uno de los gnomos de más confianza de {link:gnomeregan}Gnomeregan{/link}. El {link:gelbin-mekkatorque}Manitas Mayor Gelbin Mekkatorque{/link} contaba con él. Cuando la ciudad cayó, Thermaplugg no huyó con su pueblo. Se quedó, y se hizo amo de las ruinas. Los gnomos de {link:tinker-town}Tinker Town{/link} pronuncian su nombre como los enanos pronuncian los nombres de los {link:dark-iron-dwarves}Hierro Negro{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Thermaplugg es la razón por la que la caída de {link:gnomeregan}Gnomeregan{/link} se recuerda como una traición y no solo como un desastre. Su traición convirtió una catástrofe en una herida que los gnomos no pueden dejar cerrar. Mientras él ocupe la ciudad, no podrá recuperarse.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Traicionó al Manitas Mayor y al pueblo {link:gnomes}gnomo{/link} en la caída de {link:gnomeregan}Gnomeregan{/link}.
• Gobierna la ciudad envenenada con un ejército de gnomos leprosos, troggs y máquinas de guerra.
• Trata con los enanos {link:dark-iron-dwarves}Hierro Negro{/link}, que se mueven libremente por sus salas y ayudan en su obra.
• Está construyendo un gran artefacto de nuevo diseño, cuyos planos están en una caja fuerte junto a su trono.]=],
		},
		{
			title = "El rey de la nada",
			text = [=[Lo que quería Thermaplugg, {link:gelbin-mekkatorque}Mekkatorque{/link} todavía no sabe decirlo. Poder, quizá, o riqueza. Ambas cosas le habrían llegado con el tiempo si hubiera sabido esperar. En su lugar eligió un trono en una ruina, rodeado de los restos enloquecidos del pueblo al que antes servía. El Manitas Mayor lo llama el rey de la nada. Sin embargo, el traidor no está ocioso. Sus máquinas todavía zumban en las profundidades, y los goblins de la {link:horde}Horda{/link} susurran que su nuevo artefacto supera a todas las trituradoras que han construido jamás. Un {link:gnomes}gnomo{/link} cautivo que escapó de sus salas juró que los {link:dark-iron-dwarves}Hierro Negro{/link} habían participado en su fabricación.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de la vida de Thermaplugg antes de la caída, ni de cómo llegó a gozar de tanta confianza del Manitas Mayor.]=],
		},
	},
	chapters = {
		{
			title = "La gran traición",
			hint = "Lleve el juicio del Manitas Mayor al corazón de Gnomeregan.",
			text = [=[{link:gelbin-mekkatorque}Mekkatorque{/link} solo pidió una cosa a quienes quisieran luchar por {link:gnomeregan}Gnomeregan{/link}: que mataran al traidor. Cuando estuvo hecho, el Manitas Mayor dijo que esperaba que lo último que Thermaplugg sintiera fuera una bota. Luego habló de lo que de verdad importaba. Con el traidor muerto, los gnomos estaban un paso más cerca de volver a casa.]=],
		},
		{
			title = "El artefacto",
			hint = [=[Llévese lo que Thermaplugg guardaba bajo llave junto a su trono.]=],
			text = [=[Los planos del artefacto estaban en una caja fuerte junto a Thermaplugg, y solo él conocía la combinación. El ingeniero goblin Nogg, de {link:orgrimmar}Orgrimmar{/link}, los quería lo bastante como para enviar a extraños a la sala más profunda de {link:gnomeregan}Gnomeregan{/link}. Adonde va el ingenio {link:gnomes}gnomo{/link}, le sigue el beneficio goblin.]=],
		},
	},
	mentions = {
		{ text = "Menudo lío" },
		{ text = "La guerra de los artefactos" },
	},
	bonds = {
		{ id = "gelbin-mekkatorque", name = "Gelbin Mekkatorque", note = "el Manitas Mayor al que traicionó" },
		{ id = "grubbis", name = "Grubbis", note = "dirige a los troggs de su ciudad" },
		{ id = "dark-iron-ambassador", name = "Embajador Hierro Negro", note = "un enviado de sus aliados" },
	},
})

Translate("esES", "grubbis", {
