Translate("esES", "viscous-fallout", {
	title = "Viscous Fallout",
	subtitle = "El veneno vivo",
	found = "Las profundidades envenenadas de Gnomeregan",
	allegiance = "Ninguna",
	sections = {
		{
			title = "Resumen",
			text = [=[El Viscous Fallout es lo que dejó atrás la purga de {link:gnomeregan}Gnomeregan{/link}. Es una masa palpitante de légamo verde, nacida del veneno que inundó la ciudad, y acecha en las profundidades donde el veneno corre más espeso. Légamos y horrores más pequeños se arrastran a su alrededor. Los gnomos que estudian el veneno en {link:kharanos}Kharanos{/link} quieren muestras de tales criaturas, tomadas frescas, pues dicen que los residuos de los troggs son demasiado débiles para su trabajo.]=],
		},
		{
			title = "Importancia",
			text = [=[El Viscous Fallout es el arma de los propios gnomos hecha cuerpo. Es el único enemigo de {link:gnomeregan}Gnomeregan{/link} del que no se puede culpar a nadie más.]=],
		},
	},
})

Translate("esES", "electrocutioner-6000", {
	title = "Electrocutioner 6000",
	subtitle = "Máquina guardiana de Gnomeregan",
	found = "Las salas de Gnomeregan",
	allegiance = "Máquinas de Gnomeregan",
	sections = {
		{
			title = "Resumen",
			text = [=[El Electrocutioner 6000 es una gran máquina de guerra de {link:gnomeregan}Gnomeregan{/link}, armada con rayos. Se construyó para guardar la ciudad. Sus creadores ya no están, o están envenenados, o en el exilio, pero la máquina sigue en su puesto y abate a cualquiera que se acerque.]=],
		},
		{
			title = "Importancia",
			text = [=[El Electrocutioner muestra la cara amarga del genio {link:gnomes}gnomo{/link}. Las defensas de la ciudad se hicieron demasiado bien, y ahora la defienden contra su propio pueblo.]=],
		},
	},
})

Translate("esES", "crowd-pummeler-9-60", {
	title = "Crowd Pummeler 9-60",
	subtitle = "Luchador mecánico",
	found = "Una gran sala de Gnomeregan",
	allegiance = "Máquinas de Gnomeregan",
	sections = {
		{
			title = "Resumen",
			text = [=[El Crowd Pummeler 9-60 es una enorme máquina de {link:gnomeregan}Gnomeregan{/link}, construida, como presume su nombre, para aporrear multitudes. Todavía pisotea y golpea en una de las grandes salas de la ciudad, como si sus creadores lo estuvieran mirando. Ningún superviviente ha querido decir si los gnomos lo construyeron por deporte, para la guerra o para mantener el orden en sus calles.]=],
		},
		{
			title = "Importancia",
			text = [=[Como mucho de lo que dejaron atrás los gnomos, el Pummeler ha sobrevivido a su propósito y ha conservado su fuerza.]=],
		},
	},
})

Translate("esES", "dark-iron-ambassador", {
	title = "Embajador Hierro Negro",
	subtitle = "Enviado de los Hierro Negro",
	found = "Las salas de Gnomeregan (no siempre presente)",
	allegiance = "Enanos Hierro Negro",
	sections = {
		{
			title = "Resumen",
			text = [=[El Embajador Hierro Negro es un enviado de los {link:dark-iron-dwarves}Hierro Negro{/link}, que se encuentra a veces en las salas de {link:gnomeregan}Gnomeregan{/link}, guardado por el fuego. Qué asuntos tienen los Hierro Negro con {link:mekgineer-thermaplugg}Thermaplugg{/link} no está escrito en ninguna parte. Sin embargo, las señales son muchas: un {link:gnomes}gnomo{/link} cautivo golpeado por enanos Hierro Negro, el anillo de un joyero gnomo hallado en el cadáver de un Hierro Negro y un nuevo artefacto construido con ayuda de los Hierro Negro.]=],
		},
		{
			title = "Importancia",
			text = [=[El Embajador es la prueba de que la ruina de {link:gnomeregan}Gnomeregan{/link} forma parte de una red más amplia, y de que el viejo enemigo de {link:ironforge}Forjaz{/link} ha llegado también a la ciudad de los gnomos.]=],
		},
	},
	bonds = {
		{ id = "mekgineer-thermaplugg", name = "Mekigeniero Thermaplugg", note = "el traidor con el que trata" },
	},
})
